def anchor_cv(a, b, nanch=1000, lam=1e-2, c0=0.5, seeds=(0,1), k=10, Z=Z9, C=C0, yv=y):
    accs=[]; n=len(yv); Yv=np.eye(8)[yv]
    for s in seeds:
        f=folds(yv,k,s); S=np.zeros((n,8)); rng=np.random.RandomState(s)
        for i in range(k):
            tr=np.where(f!=i)[0]; te=np.where(f==i)[0]
            anc=rng.choice(tr, min(nanch,len(tr)), replace=False)
            Phi=gelu(a*(Z@Z[anc].T)+b); Phi=Phi-Phi[tr].mean(0); Phi/=np.sqrt((Phi[tr]**2).sum(1).mean())
            F=np.hstack([Phi, np.sqrt(c0)*(C-C[tr].mean(0))]) if c0>0 else Phi
            Wt=np.linalg.solve(F[tr].T@F[tr]+lam*np.eye(F.shape[1]), F[tr].T@(Yv[tr]-Yv[tr].mean(0)))
